<?php
declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');function out(int $s,array $b):void{http_response_code($s);echo json_encode($b,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}try{$file=__DIR__.'/../config.php';if(!is_file($file))out(503,['success'=>false,'error'=>'not_installed']);$config=require $file;$input=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($input))out(400,['success'=>false,'error'=>'invalid_json']);if((string)($input['project_key']??'')!==(string)($config['project_key']??'gpsq'))out(403,['success'=>false,'error'=>'invalid_project']);$token=trim((string)($input['token']??''));$device=trim((string)($input['device_id']??''));if($token===''||$device==='')out(422,['success'=>false,'error'=>'missing_fields']);$pdo=new PDO('sqlite:'.$config['database_path']);$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$stmt=$pdo->prepare('DELETE FROM activation_sessions WHERE token_hash=? AND device_hash=?');$stmt->execute([hash('sha256',$token),hash('sha256',$device)]);out(200,['success'=>true,'status'=>'deactivated']);}catch(Throwable $e){out(500,['success'=>false,'error'=>'server_error']);}
